1	import Ionicons from "@expo/vector-icons/Ionicons";
2	import { useRouter } from "expo-router";
3	import { useMemo, useRef, useState } from "react";
4	import {
5	  FlatList,
6	  Image,
7	  KeyboardAvoidingView,
8	  PanResponder,
9	  Platform,
10	  Pressable,
11	  ScrollView,
12	  StyleSheet,
13	  Text,
14	  TextInput,
15	  View,
16	} from "react-native";
17	import { Button } from "@/components/Buttons";
18	import { MessageBubble } from "@/components/MessageBubble";
19	import { ModelSelectorSheet } from "@/components/ModelSelectorSheet";
20	import { Screen } from "@/components/Screen";
21	import { radii, spacing, type, useKeatingTheme } from "@/constants/theme";
22	import { providerDefinition } from "@/lib/provider-config";
23	import type { ChatMessage } from "@/lib/types";
24	import { parentSessionTitle } from "@/lib/session-lineage";
25	import { useKeating } from "@/state/KeatingProvider";
26	
27	const QUICK_STARTS = [
28	  { label: "Learn a topic", prompt: "Help me learn a topic. Start by asking what I already understand." },
29	  { label: "Build a study plan", prompt: "Build me a concise study plan. Ask for the subject and my time horizon first." },
30	  { label: "Quiz me", prompt: "Quiz me on something I am learning. Ask for the topic, then give one question at a time." },
31	  { label: "Repair a misconception", prompt: "Help me find and repair a misconception. Ask me to explain the idea in my own words first." },
32	] as const;
33	
34	export default function TutorScreen() {
35	  const theme = useKeatingTheme();
36	  const colors = theme.colors;
37	  const styles = createStyles(theme);
38	  const router = useRouter();
39	  const listRef = useRef<FlatList<ChatMessage>>(null);
40	  const [draft, setDraft] = useState("");
41	  const [modelSelectorOpen, setModelSelectorOpen] = useState(false);
42	  const {
43	    state,
44	    activeSession,
45	    isGenerating,
46	    streamingMessageId,
47	    generationError,
48	    storageError,
49	    isProviderConfigured,
50	    sendMessage,
51	    retryLastResponse,
52	    stopGeneration,
53	    newSession,
54	    forkSession,
55	    selectSession,
56	    selectProviderModel,
57	    setMessageFeedback,
58	    saveArtifact,
59	  } = useKeating();
60	
61	  const savedMessageIds = useMemo(() => new Set(state.artifacts.map((artifact) => artifact.messageId)), [state.artifacts]);
62	  const provider = providerDefinition(state.providerSettings.provider);
63	  const forkParentTitle = parentSessionTitle(activeSession, state.sessions);
64	  const swipeToSessions = useMemo(
65	    () => PanResponder.create({
66	      onMoveShouldSetPanResponder: (_event, gesture) => (
67	        gesture.dx < -12
68	        && Math.abs(gesture.dx) > Math.abs(gesture.dy)
69	      ),
70	      onPanResponderRelease: (_event, gesture) => {
71	        if (gesture.dx <= -72 && Math.abs(gesture.dy) <= 48) router.push("/sessions");
72	      },
73	    }),
74	    [router],
75	  );
76	
77	  // The streaming placeholder is empty until the first token lands; hide it so
78	  // the waiting state reads as one indicator rather than a blank bubble.
79	  const visibleMessages = useMemo(
80	    () => activeSession.messages.filter((message) => message.content.length > 0),
81	    [activeSession.messages],
82	  );
83	  const awaitingFirstToken = isGenerating
84	    && activeSession.messages.some((message) => message.id === streamingMessageId && message.content.length === 0);
85	
86	  const submit = () => {
87	    const content = draft.trim();
88	    if (!content || isGenerating) return;
89	    setDraft("");
90	    void sendMessage(content);
91	  };
92	
93	  const startPrompt = (prompt: string) => {
94	    if (!isProviderConfigured) {
95	      router.push("/settings");
96	      return;
97	    }
98	    void sendMessage(prompt);
99	  };
100	
101	  return (
102	    <Screen scroll={false} contentContainerStyle={styles.screenContent}>
103	      <KeyboardAvoidingView
104	        style={styles.keyboardView}
105	        behavior={Platform.OS === "ios" ? "padding" : undefined}
106	      >
107	        <View {...swipeToSessions.panHandlers} style={styles.header}>
108	          <View style={styles.headerCopy}>
109	            <View style={styles.headerIdentityRow}>
110	              <Image accessibilityLabel="Keating" source={require("../../../assets/brand/logo-lockup.png")} style={styles.headerLockup} resizeMode="contain" />
111	              <Pressable
112	                accessibilityRole="button"
113	                accessibilityLabel={`Change model. Current model: ${provider.label} ${state.providerSettings.model}`}
114	                onPress={() => setModelSelectorOpen(true)}
115	                style={({ pressed }) => [styles.modelButton, pressed && styles.modelButtonPressed]}
116	              >
117	                <Text numberOfLines={1} style={styles.modelButtonLabel}>
118	                  {provider.label} · {state.providerSettings.model}
119	                </Text>
120	                <Ionicons name="chevron-down" size={14} color={colors.textFaint} />
121	              </Pressable>
122	            </View>
123	            {activeSession.title !== "New lesson" ? (
124	              <Text numberOfLines={1} style={styles.sessionTitle}>{activeSession.title}</Text>
125	            ) : null}
126	          </View>
127	          <Button compact variant="secondary" onPress={() => newSession()} accessibilityLabel="Start a new lesson">
128	            New lesson
129	          </Button>
130	        </View>
131	
132	        {storageError ? <Banner styles={styles} text={`Local storage: ${storageError}`} /> : null}
133	        {activeSession.parentSessionId ? (
134	          <View style={styles.forkBanner}>
135	            <View style={styles.forkCopy}>
136	              <Text style={styles.forkLabel}>Forked from</Text>
137	              <Text numberOfLines={1} style={styles.forkTitle}>{forkParentTitle}</Text>
138	            </View>
139	            {state.sessions.some((session) => session.id === activeSession.parentSessionId) ? (
140	              <Button compact variant="quiet" onPress={() => selectSession(activeSession.parentSessionId!)}>Open original</Button>
141	            ) : null}
142	          </View>
143	        ) : null}
144	        {generationError ? (
145	          <View style={styles.errorBanner} accessibilityRole="alert">
146	            <Text style={styles.errorText}>{generationError}</Text>
147	            <View style={styles.errorActions}>
148	              <Button compact variant="quiet" onPress={() => void retryLastResponse()}>Retry response</Button>
