1	import * as Haptics from "expo-haptics";
2	import {
3	  createContext,
4	  type PropsWithChildren,
5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useMemo,
9	  useRef,
10	  useState,
11	} from "react";
12	import { fetch as streamingFetch } from "expo/fetch";
13	import { DEFAULT_PROVIDER_SETTINGS, providerDefinition, PROVIDERS, settingsForProvider } from "@/lib/provider-config";
14	import { type CatalogModel, selectedProviderSettings } from "@/lib/model-catalog";
15	import { streamCompletion } from "@/lib/provider-client";
16	import { DEFAULT_TEACHER_PERSONA } from "@/lib/persona";
17	import { loadPersona, resetPersona, savePersona } from "@/lib/persona-storage";
18	import { composeSystemPrompt } from "@/lib/system-prompt";
19	import {
20	  clearPersistedState,
21	  deleteProviderKey,
22	  getProviderKey,
23	  loadPersistedState,
24	  savePersistedState,
25	  setProviderKey,
26	} from "@/lib/storage";
27	import { generateLearningArtifact } from "@/lib/learning-artifacts";
28	import { createForkedSession } from "@/lib/session-lineage";
29	import { clearCardState } from "@/state/card-state";
30	import {
31	  type ArtifactKind,
32	  type ChatMessage,
33	  type ChatSession,
34	  createId,
35	  createSession,
36	  type GeneratedArtifactKind,
37	  type MessageFeedback,
38	  type PersistedAppState,
39	  type ProviderId,
40	  type ProviderSettings,
41	} from "@/lib/types";
42	
43	type KeyStatus = Record<ProviderId, boolean>;
44	
45	interface KeatingContextValue {
46	  state: PersistedAppState;
47	  activeSession: ChatSession;
48	  hydrated: boolean;
49	  storageError: string | null;
50	  generationError: string | null;
51	  isGenerating: boolean;
52	  /** Id of the assistant message currently receiving streamed tokens. */
53	  streamingMessageId: string | null;
54	  keyStatus: KeyStatus;
55	  isProviderConfigured: boolean;
56	  persona: string;
57	  setPersona: (text: string) => Promise<void>;
58	  restoreDefaultPersona: () => Promise<void>;
59	  sendMessage: (content: string) => Promise<void>;
60	  retryLastResponse: () => Promise<void>;
61	  stopGeneration: () => void;
62	  clearGenerationError: () => void;
63	  newSession: () => string;
64	  forkSession: (sourceSessionId: string, throughMessageId?: string) => string | null;
65	  selectSession: (sessionId: string) => void;
66	  deleteSession: (sessionId: string) => void;
67	  setMessageFeedback: (messageId: string, feedback: MessageFeedback) => void;
68	  saveArtifact: (messageId: string, kind?: ArtifactKind) => void;
69	  createLearningArtifact: (topic: string, kind: GeneratedArtifactKind) => string;
70	  deleteArtifact: (artifactId: string) => void;
71	  setProvider: (provider: ProviderId) => void;
72	  selectProviderModel: (model: CatalogModel) => void;
73	  updateProviderSettings: (patch: Partial<ProviderSettings>) => void;
74	  saveApiKey: (provider: ProviderId, apiKey: string) => Promise<void>;
75	  removeApiKey: (provider: ProviderId) => Promise<void>;
76	  clearLearningData: () => Promise<void>;
77	}
78	
79	/** How often buffered stream deltas are committed to React state. */
80	const STREAM_FLUSH_INTERVAL_MS = 60;
81	
82	const emptyKeyStatus: KeyStatus = {
83	  openai: false,
84	  anthropic: false,
85	  google: false,
86	  openrouter: false,
87	  custom: false,
88	};
89	
90	function initialState(): PersistedAppState {
91	  const session = createSession();
92	  return {
93	    schemaVersion: 2,
94	    sessions: [session],
95	    activeSessionId: session.id,
96	    artifacts: [],
97	    providerSettings: DEFAULT_PROVIDER_SETTINGS,
98	    learnerFeedback: { helpful: 0, missed: 0 },
99	  };
100	}
101	
102	function normalizeState(candidate: PersistedAppState | null): PersistedAppState {
103	  if (!candidate || candidate.sessions.length === 0) return initialState();
104	  const activeExists = candidate.sessions.some((session) => session.id === candidate.activeSessionId);
105	  return {
106	    ...candidate,
107	    activeSessionId: activeExists ? candidate.activeSessionId : candidate.sessions[0].id,
108	    artifacts: Array.isArray(candidate.artifacts) ? candidate.artifacts : [],
109	    learnerFeedback: candidate.learnerFeedback ?? { helpful: 0, missed: 0 },
110	    providerSettings: candidate.providerSettings ?? DEFAULT_PROVIDER_SETTINGS,
111	  };
112	}
113	
114	function titleFromFirstMessage(content: string): string {
115	  const title = content.replace(/\s+/g, " ").trim();
116	  return title.length > 48 ? `${title.slice(0, 47)}…` : title || "New lesson";
117	}
118	
119	function artifactTitle(message: ChatMessage, kind: ArtifactKind): string {
120	  const firstLine = message.content
121	    .split("\n")
122	    .map((line) => line.replace(/^#+\s*/, "").trim())
123	    .find(Boolean);
124	  if (firstLine) return firstLine.length > 64 ? `${firstLine.slice(0, 63)}…` : firstLine;
125	  return kind === "study-plan" ? "Study plan" : kind === "quiz" ? "Practice quiz" : "Saved note";
126	}
127	
128	const KeatingContext = createContext<KeatingContextValue | null>(null);
129	
130	export function KeatingProvider({ children }: PropsWithChildren) {
131	  const [state, setState] = useState<PersistedAppState>(initialState);
132	  const [hydrated, setHydrated] = useState(false);
133	  const [persistenceReady, setPersistenceReady] = useState(false);
134	  const [storageError, setStorageError] = useState<string | null>(null);
135	  const [generationError, setGenerationError] = useState<string | null>(null);
136	  const [isGenerating, setIsGenerating] = useState(false);
137	  const [keyStatus, setKeyStatus] = useState<KeyStatus>(emptyKeyStatus);
138	  const [persona, setPersonaState] = useState<string>(DEFAULT_TEACHER_PERSONA);
139	  const [streamingMessageId, setStreamingMessageId] = useState<string | null>(null);
140	  const stateRef = useRef(state);
141	  const personaRef = useRef(persona);
142	  const abortControllerRef = useRef<AbortController | null>(null);
143	  const generationBusyRef = useRef(false);
144	
145	  personaRef.current = persona;
146	
147	  stateRef.current = state;
148	
149	  useEffect(() => {
150	    let cancelled = false;
151	    loadPersistedState()
152	      .then((persisted) => {
153	        if (cancelled) return;
154	        const next = normalizeState(persisted);
155	        stateRef.current = next;
156	        setState(next);
157	        setPersistenceReady(true);
158	      })
159	      .catch((error) => {
160	        if (!cancelled) setStorageError(error instanceof Error ? error.message : "Could not load local learning data.");
161	      })
162	      .finally(() => {
163	        if (!cancelled) setHydrated(true);
164	      });
165	
166	    Promise.all(PROVIDERS.map(async (provider) => [provider.id, Boolean(await getProviderKey(provider.id))] as const))
167	      .then((keys) => {
168	        if (!cancelled) setKeyStatus(Object.fromEntries(keys) as KeyStatus);
169	      })
170	      .catch((error) => {
171	        if (!cancelled) setStorageError(error instanceof Error ? error.message : "Could not read provider credentials.");
172	      });
173	
174	    loadPersona()
175	      .then((storedPersona) => {
176	        if (cancelled) return;
177	        personaRef.current = storedPersona;
178	        setPersonaState(storedPersona);
179	      })
180	      .catch((error) => {
181	        if (!cancelled) setStorageError(error instanceof Error ? error.message : "Could not load the tutor persona.");
182	      });
183	    return () => {
184	      cancelled = true;
185	    };
186	  }, []);
187	
188	  useEffect(() => {
189	    if (!hydrated || !persistenceReady) return;
190	    const timeout = setTimeout(() => {
191	      savePersistedState(state).catch((error) => {
192	        setStorageError(error instanceof Error ? error.message : "Could not save local learning data.");
193	      });
194	    }, 120);
195	    return () => clearTimeout(timeout);
196	  }, [hydrated, persistenceReady, state]);
197	
198	  const activeSession = useMemo(
199	    () => state.sessions.find((session) => session.id === state.activeSessionId) ?? state.sessions[0],
200	    [state.activeSessionId, state.sessions],
201	  );
202	
203	  const updateSession = useCallback((sessionId: string, update: (session: ChatSession) => ChatSession) => {
204	    setState((current) => ({
205	      ...current,
206	      sessions: current.sessions.map((session) => session.id === sessionId ? update(session) : session),
207	    }));
208	  }, []);
209	
210	  const runCompletion = useCallback(async (sessionId: string, messages: ChatMessage[]) => {
211	    const snapshot = stateRef.current;
212	    const settings = snapshot.providerSettings;
213	    const definition = providerDefinition(settings.provider);
214	    const controller = new AbortController();
215	    abortControllerRef.current = controller;
216	    generationBusyRef.current = true;
217	    setIsGenerating(true);
218	    setGenerationError(null);
219	
220	    const finishBeforeStream = () => {
221	      if (abortControllerRef.current === controller) abortControllerRef.current = null;
222	      generationBusyRef.current = false;
223	      setIsGenerating(false);
224	    };
225	
226	    let apiKey: string | null;
227	    try {
228	      apiKey = await getProviderKey(settings.provider);
229	    } catch (error) {
230	      finishBeforeStream();
231	      setGenerationError(error instanceof Error ? error.message : "Could not read the provider credential.");
232	      return;
233	    }
234	    if (controller.signal.aborted) {
235	      finishBeforeStream();
236	      return;
237	    }
238	    if (definition.requiresKey && !apiKey) {
239	      finishBeforeStream();
240	      setGenerationError(`Add your ${definition.label} API key in Settings before sending a message.`);
241	      return;
242	    }
243	
244	    // The placeholder is appended immediately so streamed tokens land in a
245	    // message the chat list is already rendering.
246	    const assistantId = createId("message");
247	    const startedAt = Date.now();
248	    updateSession(sessionId, (session) => ({
249	      ...session,
250	      messages: [...messages, { id: assistantId, role: "assistant", content: "", createdAt: startedAt }],
251	      updatedAt: startedAt,
252	    }));
253	    setStreamingMessageId(assistantId);
254	
255	    const writeContent = (content: string) => {
256	      updateSession(sessionId, (session) => ({
257	        ...session,
258	        messages: session.messages.map((message) => message.id === assistantId ? { ...message, content } : message),
259	        updatedAt: Date.now(),
260	      }));
261	    };
262	    const dropPlaceholder = () => {
263	      updateSession(sessionId, (session) => ({
264	        ...session,
265	        messages: session.messages.filter((message) => message.id !== assistantId),
266	      }));
267	    };
268	
269	    // Tokens arrive faster than the list can usefully re-render, so deltas are
270	    // buffered and flushed on a fixed cadence instead of per chunk.
271	    let pending = "";
272	    let rendered = "";
273	    const flush = () => {
274	      if (pending === rendered) return;
275	      rendered = pending;
276	      writeContent(rendered);
277	    };
278	    const flushTimer = setInterval(flush, STREAM_FLUSH_INTERVAL_MS);
279	
280	    try {
281	      const content = await streamCompletion(settings, apiKey, messages, {
282	        signal: controller.signal,
283	        systemPrompt: composeSystemPrompt(personaRef.current),
284	        fetchImpl: streamingFetch as unknown as typeof fetch,
285	        onDelta: (_delta, accumulated) => {
286	          pending = accumulated;
287	        },
288	      });
289	      clearInterval(flushTimer);
290	      writeContent(content);
291	      void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => undefined);
292	    } catch (error) {
293	      clearInterval(flushTimer);
294	      const aborted = error instanceof Error && (error.name === "AbortError" || controller.signal.aborted);
295	      // A stopped response keeps whatever was already streamed; a failed one
296	      // leaves no half-message behind.
297	      if (aborted) {
298	        if (pending.trim()) writeContent(pending.trim());
299	        else dropPlaceholder();
300	        return;
301	      }
302	      dropPlaceholder();
303	      setGenerationError(error instanceof Error ? error.message : "The model request failed.");
304	      void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error).catch(() => undefined);
305	    } finally {
306	      clearInterval(flushTimer);
307	      setStreamingMessageId((current) => current === assistantId ? null : current);
308	      if (abortControllerRef.current === controller) abortControllerRef.current = null;
309	      generationBusyRef.current = false;
310	      setIsGenerating(false);
311	    }
312	  }, [updateSession]);
313	
314	  const sendMessage = useCallback(async (content: string) => {
315	    const trimmed = content.trim();
316	    if (!trimmed || generationBusyRef.current) return;
317	    const current = stateRef.current;
318	    const session = current.sessions.find((entry) => entry.id === current.activeSessionId) ?? current.sessions[0];
319	    const message: ChatMessage = {
320	      id: createId("message"),
321	      role: "user",
322	      content: trimmed,
323	      createdAt: Date.now(),
324	    };
325	    const messages = [...session.messages, message];
326	    updateSession(session.id, (entry) => ({
327	      ...entry,
328	      title: entry.messages.length === 0 ? titleFromFirstMessage(trimmed) : entry.title,
329	      messages,
330	      updatedAt: message.createdAt,
331	    }));
332	    await runCompletion(session.id, messages);
333	  }, [runCompletion, updateSession]);
334	
335	  const retryLastResponse = useCallback(async () => {
336	    if (generationBusyRef.current) return;
337	    const current = stateRef.current;
338	    const session = current.sessions.find((entry) => entry.id === current.activeSessionId) ?? current.sessions[0];
339	    let userIndex = -1;
340	    for (let index = session.messages.length - 1; index >= 0; index -= 1) {
341	      if (session.messages[index].role === "user") {
342	        userIndex = index;
343	        break;
344	      }
345	    }
346	    if (userIndex < 0) return;
347	    const messages = session.messages.slice(0, userIndex + 1);
348	    updateSession(session.id, (entry) => ({ ...entry, messages, updatedAt: Date.now() }));
349	    await runCompletion(session.id, messages);
350	  }, [runCompletion, updateSession]);
351	
352	  const stopGeneration = useCallback(() => {
353	    abortControllerRef.current?.abort();
354	    abortControllerRef.current = null;
355	  }, []);
356	
357	  const newSession = useCallback(() => {
358	    stopGeneration();
359	    const session = createSession();
360	    setState((current) => ({
361	      ...current,
362	      sessions: [session, ...current.sessions],
363	      activeSessionId: session.id,
364	    }));
365	    void Haptics.selectionAsync().catch(() => undefined);
366	    return session.id;
367	  }, [stopGeneration]);
368	
369	  const forkSession = useCallback((sourceSessionId: string, throughMessageId?: string) => {
370	    if (generationBusyRef.current) return null;
371	    const source = stateRef.current.sessions.find((session) => session.id === sourceSessionId);
372	    if (!source) return null;
373	    let fork: ChatSession;
374	    try {
375	      fork = createForkedSession(source, { throughMessageId });
376	    } catch (error) {
377	      setStorageError(error instanceof Error ? error.message : "Could not fork this lesson.");
378	      return null;
379	    }
380	    setState((current) => ({
381	      ...current,
382	      sessions: [fork, ...current.sessions],
383	      activeSessionId: fork.id,
384	    }));
385	    void Haptics.selectionAsync().catch(() => undefined);
386	    return fork.id;
387	  }, []);
388	
389	  const selectSession = useCallback((sessionId: string) => {
390	    if (!stateRef.current.sessions.some((session) => session.id === sessionId)) return;
391	    stopGeneration();
392	    setState((current) => ({ ...current, activeSessionId: sessionId }));
393	  }, [stopGeneration]);
394	
395	  const deleteSession = useCallback((sessionId: string) => {
396	    stopGeneration();
397	    setState((current) => {
398	      const remaining = current.sessions.filter((session) => session.id !== sessionId);
399	      if (remaining.length === 0) remaining.push(createSession());
400	      return {
401	        ...current,
402	        sessions: remaining,
403	        activeSessionId: current.activeSessionId === sessionId ? remaining[0].id : current.activeSessionId,
404	        artifacts: current.artifacts.filter((artifact) => artifact.sessionId !== sessionId),
405	      };
406	    });
407	  }, [stopGeneration]);
408	
409	  const setMessageFeedback = useCallback((messageId: string, feedback: MessageFeedback) => {
410	    setState((current) => {
411	      let previous: MessageFeedback | undefined;
412	      const sessions = current.sessions.map((session) => ({
413	        ...session,
414	        messages: session.messages.map((message) => {
415	          if (message.id !== messageId) return message;
416	          previous = message.feedback;
417	          return { ...message, feedback };
418	        }),
419	      }));
420	      if (!previous && sessions.every((session) => session.messages.every((message) => message.id !== messageId))) {
421	        return current;
422	      }
423	      const learnerFeedback = { ...current.learnerFeedback };
424	      if (previous) learnerFeedback[previous] = Math.max(0, learnerFeedback[previous] - 1);
425	      learnerFeedback[feedback] += 1;
426	      return { ...current, sessions, learnerFeedback };
427	    });
428	    void Haptics.selectionAsync().catch(() => undefined);
429	  }, []);
430	
431	  const saveArtifact = useCallback((messageId: string, kind: ArtifactKind = "note") => {
432	    setState((current) => {
433	      if (current.artifacts.some((artifact) => artifact.messageId === messageId)) return current;
434	      const session = current.sessions.find((entry) => entry.messages.some((message) => message.id === messageId));
435	      const message = session?.messages.find((entry) => entry.id === messageId);
436	      if (!session || !message || message.role !== "assistant") return current;
437	      return {
438	        ...current,
439	        artifacts: [{
440	          id: createId("artifact"),
441	          sessionId: session.id,
442	          messageId,
443	          kind,
444	          source: "assistant",
445	          title: artifactTitle(message, kind),
446	          content: message.content,
447	          createdAt: Date.now(),
448	        }, ...current.artifacts],
449	      };
450	    });
451	    void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => undefined);
452	  }, []);
453	
454	  const createLearningArtifact = useCallback((topicName: string, kind: GeneratedArtifactKind) => {
455	    const generated = generateLearningArtifact(topicName, kind);
456	    const id = createId("artifact");
457	    setState((current) => ({
458	      ...current,
459	      artifacts: [{
460	        id,
461	        kind: generated.kind,
462	        source: "keating-core",
463	        topic: generated.topic,
464	        title: generated.title,
465	        content: generated.content,
466	        createdAt: Date.now(),
467	      }, ...current.artifacts],
468	    }));
469	    void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => undefined);
470	    return id;
471	  }, []);
472	
473	  const deleteArtifact = useCallback((artifactId: string) => {
474	    setState((current) => ({
475	      ...current,
476	      artifacts: current.artifacts.filter((artifact) => artifact.id !== artifactId),
477	    }));
478	  }, []);
479	
480	  const setProvider = useCallback((provider: ProviderId) => {
481	    setState((current) => ({ ...current, providerSettings: settingsForProvider(provider) }));
482	  }, []);
483	
484	  const selectProviderModel = useCallback((model: CatalogModel) => {
485	    setState((current) => ({
486	      ...current,
487	      providerSettings: selectedProviderSettings(current.providerSettings, model),
488	    }));
489	    void Haptics.selectionAsync().catch(() => undefined);
490	  }, []);
491	
492	  const updateProviderSettings = useCallback((patch: Partial<ProviderSettings>) => {
493	    setState((current) => ({
494	      ...current,
495	      providerSettings: { ...current.providerSettings, ...patch },
496	    }));
497	  }, []);
498	
499	  const saveApiKey = useCallback(async (provider: ProviderId, apiKey: string) => {
500	    const trimmed = apiKey.trim();
501	    if (!trimmed) throw new Error("Enter an API key before saving.");
502	    await setProviderKey(provider, trimmed);
503	    setKeyStatus((current) => ({ ...current, [provider]: true }));
504	  }, []);
505	
506	  const removeApiKey = useCallback(async (provider: ProviderId) => {
507	    await deleteProviderKey(provider);
508	    setKeyStatus((current) => ({ ...current, [provider]: false }));
509	  }, []);
510	
511	  const setPersona = useCallback(async (text: string) => {
512	    const next = text.trim().length > 0 ? text : DEFAULT_TEACHER_PERSONA;
513	    personaRef.current = next;
514	    setPersonaState(next);
515	    await savePersona(next);
516	  }, []);
517	
518	  const restoreDefaultPersona = useCallback(async () => {
519	    personaRef.current = DEFAULT_TEACHER_PERSONA;
520	    setPersonaState(DEFAULT_TEACHER_PERSONA);
521	    await resetPersona();
522	  }, []);
523	
524	  const clearLearningData = useCallback(async () => {
525	    stopGeneration();
526	    clearCardState();
527	    await clearPersistedState();
528	    const next = initialState();
529	    stateRef.current = next;
530	    setState(next);
531	    setPersistenceReady(true);
532	    setStorageError(null);
533	  }, [stopGeneration]);
534	
535	  const definition = providerDefinition(state.providerSettings.provider);
536	  const isProviderConfigured = !definition.requiresKey || keyStatus[state.providerSettings.provider];
537	
538	  const value = useMemo<KeatingContextValue>(() => ({
539	    state,
540	    activeSession,
