1	import { KEATING_MOBILE_SYSTEM_PROMPT } from "./system-prompt";
2	import type { ChatMessage, ProviderSettings } from "./types";
3	
4	export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;
5	
6	export interface ProviderRequest {
7	  url: string;
8	  init: RequestInit;
9	}
10	
11	export interface ProviderRequestOptions {
12	  signal?: AbortSignal;
13	  /** Ask the provider for a Server-Sent Events token stream. */
14	  stream?: boolean;
15	  /** Composed persona + teaching protocol. Defaults to the built-in prompt. */
16	  systemPrompt?: string;
17	}
18	
19	const MAX_HISTORY_MESSAGES = 40;
20	
21	function withoutTrailingSlash(value: string): string {
22	  return value.trim().replace(/\/+$/, "");
23	}
24	
25	function openAiChatUrl(baseUrl: string): string {
26	  const base = withoutTrailingSlash(baseUrl);
27	  if (base.endsWith("/chat/completions")) return base;
28	  if (base.endsWith("/v1")) return `${base}/chat/completions`;
29	  return `${base}/v1/chat/completions`;
30	}
31	
32	function openAiResponsesUrl(baseUrl: string): string {
33	  const base = withoutTrailingSlash(baseUrl);
34	  if (base.endsWith("/responses")) return base;
35	  if (base.endsWith("/v1")) return `${base}/responses`;
36	  return `${base}/v1/responses`;
37	}
38	
39	function recentMessages(messages: ChatMessage[]) {
40	  const window = messages
41	    .filter((message) => message.content.trim().length > 0)
42	    .slice(-MAX_HISTORY_MESSAGES);
43	
44	  // Anthropic requires the first conversation message to be a user turn, and
45	  // Gemini has the same practical alternation expectation for contents. When a
46	  // long transcript ending in the newest user prompt is sliced to an even-sized
47	  // window, the first retained turn can be the prior assistant response. Drop
48	  // any leading assistant-only context so every provider receives a valid
49	  // user-started transcript.
50	  while (window[0]?.role === "assistant") window.shift();
51	  return window;
52	}
53	
54	export function buildProviderRequest(
55	  settings: ProviderSettings,
56	  apiKey: string | null,
57	  messages: ChatMessage[],
58	  options: ProviderRequestOptions = {},
59	): ProviderRequest {
60	  const { signal, stream = false, systemPrompt = KEATING_MOBILE_SYSTEM_PROMPT } = options;
61	  const history = recentMessages(messages);
62	  const commonHeaders: Record<string, string> = { "Content-Type": "application/json" };
63	  if (stream) commonHeaders.Accept = "text/event-stream";
64	
65	  if (settings.provider === "openai") {
66	    if (apiKey) commonHeaders.Authorization = `Bearer ${apiKey}`;
67	    return {
68	      url: openAiResponsesUrl(settings.baseUrl),
69	      init: {
70	        method: "POST",
71	        headers: commonHeaders,
72	        signal,
73	        body: JSON.stringify({
74	          model: settings.model,
75	          instructions: systemPrompt,
76	          input: history.map((message) => ({ role: message.role, content: message.content })),
77	          ...(stream ? { stream: true } : {}),
78	        }),
79	      },
80	    };
81	  }
82	
83	  if (settings.provider === "anthropic") {
84	    if (apiKey) commonHeaders["x-api-key"] = apiKey;
85	    commonHeaders["anthropic-version"] = "2023-06-01";
86	    return {
87	      url: `${withoutTrailingSlash(settings.baseUrl)}/messages`,
88	      init: {
89	        method: "POST",
90	        headers: commonHeaders,
91	        signal,
92	        body: JSON.stringify({
93	          model: settings.model,
94	          system: systemPrompt,
95	          max_tokens: 4096,
96	          temperature: settings.temperature,
97	          ...(stream ? { stream: true } : {}),
98	          messages: history.map((message) => ({ role: message.role, content: message.content })),
99	        }),
100	      },
101	    };
102	  }
103	
104	  if (settings.provider === "google") {
105	    const encodedModel = encodeURIComponent(settings.model);
106	    const method = stream ? "streamGenerateContent" : "generateContent";
107	    const params = new URLSearchParams();
108	    if (stream) params.set("alt", "sse");
109	    if (apiKey) params.set("key", apiKey);
110	    const query = params.toString();
111	    return {
112	      url: `${withoutTrailingSlash(settings.baseUrl)}/models/${encodedModel}:${method}${query ? `?${query}` : ""}`,
113	      init: {
114	        method: "POST",
115	        headers: commonHeaders,
116	        signal,
117	        body: JSON.stringify({
118	          systemInstruction: { parts: [{ text: systemPrompt }] },
119	          contents: history.map((message) => ({
120	            role: message.role === "assistant" ? "model" : "user",
121	            parts: [{ text: message.content }],
122	          })),
123	          generationConfig: { temperature: settings.temperature, maxOutputTokens: 4096 },
124	        }),
125	      },
126	    };
127	  }
128	
129	  if (apiKey) commonHeaders.Authorization = `Bearer ${apiKey}`;
130	  if (settings.provider === "openrouter") {
131	    commonHeaders["HTTP-Referer"] = "https://keating.help";
132	    commonHeaders["X-Title"] = "Keating Mobile";
133	  }
134	
135	  return {
136	    url: openAiChatUrl(settings.baseUrl),
137	    init: {
138	      method: "POST",
139	      headers: commonHeaders,
140	      signal,
141	      body: JSON.stringify({
142	        model: settings.model,
143	        temperature: settings.temperature,
144	        ...(stream ? { stream: true } : {}),
145	        messages: [
146	          { role: "system", content: systemPrompt },
147	          ...history.map((message) => ({ role: message.role, content: message.content })),
148	        ],
149	      }),
150	    },
151	  };
152	}
153	
154	function providerErrorMessage(payload: unknown, fallback: string): string {
155	  if (typeof payload !== "object" || payload === null) return fallback;
156	  const record = payload as Record<string, unknown>;
157	  const error = record.error;
158	  if (typeof error === "string" && error.trim()) return error;
159	  if (typeof error === "object" && error !== null) {
160	    const message = (error as Record<string, unknown>).message;
161	    if (typeof message === "string" && message.trim()) return message;
