1	import {
2	  anthropicMaxTokens,
3	  anthropicThinkingBudget,
4	  googleThinkingBudget,
5	  openAiReasoningEffort,
6	} from "./reasoning";
7	import { KEATING_MOBILE_SYSTEM_PROMPT } from "./system-prompt";
8	import type { ChatMessage, ProviderSettings } from "./types";
9	import type { ReasoningLevel } from "./ui-settings";
10	
11	export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;
12	
13	export interface ProviderRequest {
14	  url: string;
15	  init: RequestInit;
16	}
17	
18	export interface ProviderRequestOptions {
19	  signal?: AbortSignal;
20	  /** Ask the provider for a Server-Sent Events token stream. */
21	  stream?: boolean;
22	  /** Composed persona + teaching protocol. Defaults to the built-in prompt. */
23	  systemPrompt?: string;
24	}
25	
26	const MAX_HISTORY_MESSAGES = 40;
27	
28	function withoutTrailingSlash(value: string): string {
29	  return value.trim().replace(/\/+$/, "");
30	}
31	
32	function openAiChatUrl(baseUrl: string): string {
33	  const base = withoutTrailingSlash(baseUrl);
34	  if (base.endsWith("/chat/completions")) return base;
35	  if (base.endsWith("/v1")) return `${base}/chat/completions`;
36	  return `${base}/v1/chat/completions`;
37	}
38	
39	function openAiResponsesUrl(baseUrl: string): string {
40	  const base = withoutTrailingSlash(baseUrl);
41	  if (base.endsWith("/responses")) return base;
42	  if (base.endsWith("/v1")) return `${base}/responses`;
43	  return `${base}/v1/responses`;
44	}
45	
46	function recentMessages(messages: ChatMessage[]) {
47	  const window = messages
48	    .filter((message) => message.content.trim().length > 0)
49	    .slice(-MAX_HISTORY_MESSAGES);
50	
51	  // Anthropic requires the first conversation message to be a user turn, and
52	  // Gemini has the same practical alternation expectation for contents. When a
53	  // long transcript ending in the newest user prompt is sliced to an even-sized
54	  // window, the first retained turn can be the prior assistant response. Drop
55	  // any leading assistant-only context so every provider receives a valid
56	  // user-started transcript.
57	  while (window[0]?.role === "assistant") window.shift();
58	  return window;
59	}
60	
61	export function buildProviderRequest(
62	  settings: ProviderSettings,
63	  apiKey: string | null,
64	  messages: ChatMessage[],
65	  options: ProviderRequestOptions = {},
66	): ProviderRequest {
67	  const { signal, stream = false, systemPrompt = KEATING_MOBILE_SYSTEM_PROMPT } = options;
68	  const history = recentMessages(messages);
69	  const commonHeaders: Record<string, string> = { "Content-Type": "application/json" };
70	  if (stream) commonHeaders.Accept = "text/event-stream";
71	
72	  if (settings.provider === "openai") {
73	    if (apiKey) commonHeaders.Authorization = `Bearer ${apiKey}`;
74	    return {
75	      url: openAiResponsesUrl(settings.baseUrl),
76	      init: {
77	        method: "POST",
78	        headers: commonHeaders,
79	        signal,
80	        body: JSON.stringify({
81	          model: settings.model,
82	          instructions: systemPrompt,
83	          input: history.map((message) => ({ role: message.role, content: message.content })),
84	          ...(stream ? { stream: true } : {}),
85	        }),
86	      },
87	    };
88	  }
89	
90	  if (settings.provider === "anthropic") {
91	    if (apiKey) commonHeaders["x-api-key"] = apiKey;
92	    commonHeaders["anthropic-version"] = "2023-06-01";
93	    return {
94	      url: `${withoutTrailingSlash(settings.baseUrl)}/messages`,
95	      init: {
96	        method: "POST",
97	        headers: commonHeaders,
98	        signal,
99	        body: JSON.stringify({
