import "react-native-gesture-handler";

import { Stack } from "expo-router";
import * as SplashScreen from "expo-splash-screen";
import { SpaceMono_400Regular, SpaceMono_700Bold, useFonts } from "@expo-google-fonts/space-mono";
import { StatusBar } from "expo-status-bar";
import { useEffect } from "react";
import { ActivityIndicator, Image, StyleSheet, View } from "react-native";
import { GestureHandlerRootView } from "react-native-gesture-handler";
import { SafeAreaProvider } from "react-native-safe-area-context";
import { KeatingThemeProvider, spacing, useKeatingTheme } from "@/constants/theme";
import { KeatingProvider, useKeating } from "@/state/KeatingProvider";

void SplashScreen.preventAutoHideAsync();

function AppNavigator() {
  const { hydrated } = useKeating();
  const theme = useKeatingTheme();
  const [fontsLoaded] = useFonts({ SpaceMono: SpaceMono_400Regular, SpaceMonoBold: SpaceMono_700Bold });

  useEffect(() => {
    if (hydrated && fontsLoaded) void SplashScreen.hideAsync();
  }, [fontsLoaded, hydrated]);

  if (!hydrated || !fontsLoaded) {
    return (
      <View style={[styles.loading, { backgroundColor: theme.colors.background }]}>
        <Image accessibilityLabel="Keating" source={require("../../assets/brand/logo-lockup.png")} style={styles.lockup} resizeMode="contain" />
        <ActivityIndicator color={theme.colors.primary} size="small" />
      </View>
    );
  }

  return (
    <>
      <StatusBar style={theme.statusBarStyle} />
      <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: theme.colors.background } }} />
    </>
  );
}

export default function RootLayout() {
  return (
    <GestureHandlerRootView style={styles.root}>
      <SafeAreaProvider>
        <KeatingThemeProvider>
          <KeatingProvider>
            <AppNavigator />
          </KeatingProvider>
        </KeatingThemeProvider>
      </SafeAreaProvider>
    </GestureHandlerRootView>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  loading: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    gap: spacing.xl,
    backgroundColor: "transparent",
  },
  lockup: { width: 176, height: 56 },
});

