30	  const appVersion = Constants.expoConfig?.version ?? "Unavailable";
31	  const {
32	    state,
33	    keyStatus,
34	    setProvider,
35	    updateProviderSettings,
36	    saveApiKey,
37	    removeApiKey,
38	    clearLearningData,
