49	  const [personaSaved, setPersonaSaved] = useState(false);
50	  const [contextDraft, setContextDraft] = useState(learnerContext);
51	  const [contextSaved, setContextSaved] = useState(false);
52	  const [keyError, setKeyError] = useState<string | null>(null);
53	  const [savingKey, setSavingKey] = useState(false);
54	  const settings = state.providerSettings;
55	  const definition = providerDefinition(settings.provider);
56	  const hasKey = keyStatus[settings.provider];
57	
58	  useEffect(() => {
59	    setApiKey("");
60	    setKeyError(null);
61	  }, [settings.provider]);
62	
63	  // Follow the stored persona when it changes outside this screen (hydration,
64	  // reset) without clobbering an in-progress edit.
65	  useEffect(() => {
66	    setPersonaDraft(persona);
67	    setPersonaSaved(false);
68	  }, [persona]);
69	
70	  useEffect(() => {
71	    setContextDraft(learnerContext);
72	    setContextSaved(false);
73	  }, [learnerContext]);
74	
75	  const chooseProvider = (provider: ProviderId) => {
76	    setProvider(provider);
77	  };
