79	  const storeKey = async () => {
80	    setSavingKey(true);
81	    setKeyError(null);
82	    try {
83	      await saveApiKey(settings.provider, apiKey);
84	      setApiKey("");
85	    } catch (error) {
86	      setKeyError(error instanceof Error ? error.message : "Could not store the API key.");
87	    } finally {
88	      setSavingKey(false);
89	    }
90	  };
91	
92	  const confirmRemoveKey = () => {
93	    Alert.alert("Remove API key?", `Keating will no longer be able to use ${definition.label} on this device.`, [
94	      { text: "Cancel", style: "cancel" },
95	      { text: "Remove key", style: "destructive", onPress: () => void removeApiKey(settings.provider) },
96	    ]);
97	  };
98	
99	  const confirmClearData = () => {
100	    Alert.alert(
101	      "Clear local learning data?",
102	      "All sessions, feedback, and saved notes will be removed. Provider keys will stay in secure storage.",
103	      [
104	        { text: "Cancel", style: "cancel" },
105	        { text: "Clear learning data", style: "destructive", onPress: () => void clearLearningData() },
106	      ],
107	    );
108	  };
109	
110	  return (
111	    <Screen title="Settings" subtitle="Appearance, provider, teaching style, and on-device data">
112	      <Section title="Appearance" body="How Keating looks on this device.">
113	        <FieldLabel>Theme</FieldLabel>
114	        <ChoiceRow
115	          options={THEME_OPTIONS}
116	          selected={uiSettings.theme}
117	          onSelect={(theme) => updateSettings({ theme })}
118	        />
119	        <FieldLabel>Font</FieldLabel>
120	        <View style={styles.optionList}>
121	          {FONT_FAMILY_OPTIONS.map((option) => (
122	            <OptionRow
123	              key={option.value}
124	              label={option.label}
125	              description={option.description}
126	              selected={uiSettings.fontFamily === option.value}
127	              onPress={() => updateSettings({ fontFamily: option.value })}
128	            />
129	          ))}
130	        </View>
131	      </Section>
132	
133	      <Section title="Chat" body="What the tutor shows you while it teaches.">
134	        <ToggleRow
135	          label="Interactive cards"
136	          description="Render quizzes, question forms, and goals as cards you can answer in place."
137	          value={uiSettings.showToolUi}
138	          onValueChange={(showToolUi) => updateSettings({ showToolUi })}
139	        />
140	        <ToggleRow
