import {
  CourseAuthorizationError,
  CourseConflictError,
  CourseNotFoundError,
} from "../../../src/courses/operations";
import { NotOrganicOperationalError } from "../../../src/notorganic-provider/server";
import {
  applyStoredCourseOperation,
  CourseEnrollmentConsentRequiredError,
  createCourse,
  createCourseInvite,
  getCourseForAccount,
