import type { PropsWithChildren, ReactNode } from "react";
import { ScrollView, StyleSheet, Text, View, type ScrollViewProps } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { spacing, useKeatingTheme } from "@/constants/theme";

interface ScreenProps extends PropsWithChildren {
  title?: string;
  subtitle?: string;
  action?: ReactNode;
  scroll?: boolean;
  contentContainerStyle?: ScrollViewProps["contentContainerStyle"];
}

export function Screen({
  children,
  title,
  subtitle,
  action,
  scroll = true,
  contentContainerStyle,
}: ScreenProps) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const content = (
    <View style={[styles.content, contentContainerStyle]}>
      {(title || action) && (
        <View style={styles.header}>
          <View style={styles.headerCopy}>
            {title ? <Text style={styles.title}>{title}</Text> : null}
            {subtitle ? <Text style={styles.subtitle}>{subtitle}</Text> : null}
          </View>
          {action}
        </View>
      )}
      {children}
    </View>
  );

  return (
    <SafeAreaView style={styles.safeArea} edges={["top", "left", "right"]}>
      {scroll ? (
        <ScrollView
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          {content}
        </ScrollView>
      ) : content}
    </SafeAreaView>
  );
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors, type } = theme;
  return StyleSheet.create({
  safeArea: { flex: 1, backgroundColor: colors.background },
  scrollContent: { flexGrow: 1 },
  content: {
    width: "100%",
    maxWidth: 760,
    flex: 1,
    alignSelf: "center",
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.md,
    paddingBottom: spacing.xxl,
  },
  header: {
    minHeight: 64,
    flexDirection: "row",
    alignItems: "flex-start",
    justifyContent: "space-between",
    gap: spacing.md,
    marginBottom: spacing.xl,
  },
  headerCopy: { flex: 1, minWidth: 0 },
  title: { ...type.title, color: colors.text },
  subtitle: { ...type.body, marginTop: spacing.xs, color: colors.textMuted },
  });
}
import { Image, StyleSheet, Text, View } from "react-native";
import type { ReactNode } from "react";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";

export function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  const styles = createStyles(useKeatingTheme());
  return (
    <View style={styles.container}>
      <Image
        accessibilityIgnoresInvertColors
        accessibilityLabel="Keating"
        source={require("../../assets/brand/logo-lockup.png")}
        style={styles.mark}
        resizeMode="contain"
      />
      <Text style={styles.title}>{title}</Text>
      <Text style={styles.body}>{body}</Text>
      {action ? <View style={styles.action}>{action}</View> : null}
    </View>
  );
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors, type } = theme;
  return StyleSheet.create({
  container: {
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: spacing.xl,
    paddingVertical: 40,
    borderRadius: radii.lg,
    backgroundColor: colors.surface,
    borderWidth: 1,
    borderColor: colors.border,
  },
  mark: { width: 132, height: 44, marginBottom: spacing.md },
  title: { ...type.heading, color: colors.text, textAlign: "center" },
  body: { ...type.body, color: colors.textMuted, textAlign: "center", marginTop: spacing.sm, maxWidth: 420 },
  action: { marginTop: spacing.xl, minWidth: 160 },
  });
}

