import Ionicons from "@expo/vector-icons/Ionicons";
import { Image, StyleSheet, Text, View } from "react-native";
import { Button } from "@/components/Buttons";
import { Screen } from "@/components/Screen";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import { openProductLink } from "@/lib/open-product-link";
import { PRODUCT_LINKS } from "@/lib/product-links";

const COURSE_CAPABILITIES = [
  "Course library and workspaces",
  "Assignments and learner artifacts",
  "Discussion, reactions, and consent controls",
] as const;

export default function CoursesScreen() {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const { colors } = theme;

  return (
    <Screen title="Courses" subtitle="Structured learning with your class or study group">
      <View style={styles.hero}>
        <Image
          accessible={false}
          accessibilityIgnoresInvertColors
