  const [acceptTeacherAccess, setAcceptTeacherAccess] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!visible) return;
    setCode("");
    setAcceptTeacherAccess(false);
    setError(null);
  }, [visible]);

  const submit = async () => {
    const trimmed = code.trim();
    if (!trimmed) return;
    setBusy(true);
    setError(null);
