      borderRadius: radii.sm,
      borderWidth: 1,
      borderColor: colors.border,
    },
    iconButtonPressed: { backgroundColor: colors.surfacePressed },
    input: {
      ...type.body,
      flex: 1,
      minWidth: 0,
      minHeight: 44,
      maxHeight: 160,
      paddingHorizontal: spacing.sm,
      paddingVertical: spacing.sm,
      color: colors.text,
      textAlignVertical: "center",
    },
